const $=id=>document.getElementById(id), W=11,H=11, names=['The Verdant Reach','The Shattered Ford','Ashenwood Crossing','The Sunken Crown','The Briar March'];
let chosen=[],units=[],terrain=[],battle=1,phase='player',selected=null,inspectId=null,moveSet=new Map(),mode='move',logItems=[],gameBusy=false,duelBusy=false,canvas=$('mapCanvas'),ctx=canvas.getContext('2d'),geom=null,drag=null,toastTimer;
function alive(u){return u.hp>0}function byId(id){return units.find(u=>u.id===id)}function unitAt(x,y){return units.find(u=>alive(u)&&u.x===x&&u.y===y)}function key(x,y){return x+','+y}function distance(a,b){return Math.max(Math.abs(a.x-b.x),Math.abs(a.y-b.y))}function canReach(a,b){let d=distance(a,b);return d>=1&&d<=a.range}
function showScreen(id){document.querySelectorAll('.screen').forEach(e=>e.classList.remove('active'));$(id).classList.add('active')}
$('beginBtn').onclick=()=>{showScreen('deployScreen');renderDeploy()};
function renderDeploy(){let grid=$('heroGrid');grid.innerHTML=heroes.map(h=>`<button class="hero-card ${chosen.includes(h.id)?'selected':''}" data-id="${h.id}" style="--c:${h.c}"><span class="avatar">${h.icon}</span><span><strong>${h.name}</strong><small>${h.cls}</small><em>HP ${h.hp} · ATK ${h.atk} · DEF ${h.def} · MOV ${h.move}</em></span><i class="pick">${chosen.includes(h.id)?'✓':''}</i></button>`).join('');grid.querySelectorAll('.hero-card').forEach(b=>b.onclick=()=>{let id=b.dataset.id;if(chosen.includes(id))chosen=chosen.filter(x=>x!==id);else if(chosen.length<5)chosen.push(id);else toast('Choose exactly five heroes');renderDeploy()});$('pickCount').textContent=chosen.length;$('deployBtn').disabled=chosen.length!==5}
$('deployBtn').onclick=()=>{battle=1;startBattle()};
function generateMap(){terrain=Array.from({length:H},(_,y)=>Array.from({length:W},(_,x)=>{if(x<2||x>8)return 'plain';let n=Math.random();return n<.11?'water':n<.22?'mountain':n<.43?'forest':'plain'}));for(let y=0;y<H;y++){terrain[y][0]=terrain[y][1]='plain';terrain[y][9]=terrain[y][10]='plain'}
 units=chosen.map((id,i)=>{let h=heroes.find(a=>a.id===id),spots=[[0,2],[1,4],[0,6],[1,8],[0,9]],p=spots[i];return {...h,team:'player',hp:h.hp,maxHp:h.hp,x:p[0],y:p[1],acted:false,moved:false}});
 let count=Math.min(9,5+Math.floor((battle-1)/2));for(let i=0;i<count;i++){let et=enemyTypes[Math.random()<.2?2:Math.random()<.55?0:1],pos=[[9,1],[10,3],[9,5],[10,7],[9,9],[8,2],[10,5],[8,8],[9,10]][i],scale=battle-1;units.push({...et,id:'enemy'+i,team:'enemy',hp:et.hp+2*scale,maxHp:et.hp+2*scale,atk:et.atk+scale,x:pos[0],y:pos[1],acted:false,moved:false})}
}
function startBattle(){generateMap();phase='player';selected=null;inspectId=null;mode='move';logItems=[];gameBusy=false;duelBusy=false;$('battleBadge').textContent=`BATTLE ${String(battle).padStart(2,'0')}`;$('battleNum').textContent=`BATTLE ${String(battle).padStart(2,'0')}`;$('mapName').textContent='✧ '+names[(battle-1)%names.length];$('resultModal').classList.remove('show');showScreen('battleScreen');addLog(`Battle ${battle}: your company takes the field.`);renderAll();resizeCanvas()}
function terrainCost(x,y,u){let t=terrain[y][x];if((t==='water'||t==='mountain')&&!u.fly)return Infinity;if(u.fly)return 1;return t==='forest'?2:1}
function reachable(u,max=u.move){let distMap=new Map([[key(u.x,u.y),0]]),todo=[[u.x,u.y,0]];for(let i=0;i<todo.length;i++){let [x,y,c]=todo[i];for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(!dx&&!dy)continue;let nx=x+dx,ny=y+dy;if(nx<0||ny<0||nx>=W||ny>=H|| (unitAt(nx,ny)&&!(nx===u.x&&ny===u.y)))continue;let nc=c+terrainCost(nx,ny,u),k=key(nx,ny);if(nc>max||nc===Infinity||(distMap.has(k)&&distMap.get(k)<=nc))continue;distMap.set(k,nc);todo.push([nx,ny,nc])}}return distMap}
function setSelection(u){if(!u||!alive(u))return;inspectId=u.id;if(u.team==='player'&&phase==='player'&&!u.acted&&!gameBusy){selected=u.id;mode=u.moved?'action':'move';moveSet=u.moved?new Map():reachable(u);renderAll()}else{inspectId=u.id;renderAll()}}
function addLog(text){logItems.unshift(text);logItems=logItems.slice(0,8);$('log').innerHTML=logItems.map(s=>`<p>${s}</p>`).join('')}
function toast(msg){let t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),1500)}

