function toast(msg){let t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),1500)}
function renderAll(){drawMap();renderRoster();renderInspect();renderControls();$('phaseText').textContent=phase==='player'?'Player Phase':phase==='enemy'?'Enemy Phase':'Victory';$('objective').innerHTML=`Defeat every enemy<br>${units.filter(u=>u.team==='enemy'&&alive(u)).length} bandits remain`;$('standing').textContent=`${units.filter(u=>u.team==='player'&&alive(u)).length} standing`}
function renderRoster(){let list=$('roster');list.innerHTML=units.filter(u=>u.team==='player').map(u=>`<div class="roster-row ${u.id===selected?'sel':''} ${!alive(u)?'dead':''}" data-id="${u.id}" style="--c:${u.c}"><span class="roster-dot">${u.icon}</span><strong>${u.name}${u.acted&&alive(u)?' ·':''}</strong><span class="mini-hp">${u.hp}/${u.maxHp}</span></div>`).join('');list.querySelectorAll('.roster-row').forEach(el=>el.onclick=()=>setSelection(byId(el.dataset.id)))}
function renderInspect(){let u=byId(inspectId)||byId(selected)||units.find(x=>x.team==='player');if(!u)return;$('inspect').innerHTML=`<div class="info-title">Unit status <small>${u.team==='player'?'ALLY':'ENEMY'}${u.acted&&alive(u)?' · ACTED':''}</small></div><div class="unit-name" style="--c:${u.c}"><div class="unit-face">${u.icon}</div><div><strong>${u.name}</strong><small>${u.cls} · ${u.weapon}</small></div></div><div class="hp-line"><i style="width:${100*Math.max(0,u.hp)/u.maxHp}%;background:${u.hp/u.maxHp<.35?'#bd6557':''}"></i></div><div class="hp-caption"><span>HP ${u.hp} / ${u.maxHp}</span><span>${u.hp<=0?'FALLEN':u.acted?'ACTED':'READY'}</span></div><div class="stats"><span><b>${u.atk}</b> ATK</span><span><b>${u.def}</b> DEF</span><span><b>${u.move}</b> MOV</span><span><b>${u.range}</b> RNG</span>${u.heal?`<span><b>${u.heal}</b> HEAL</span>`:''}</div>`}
function renderControls(){let u=byId(selected),ready=!!u&&alive(u)&&!u.acted&&phase==='player'&&!gameBusy;let possibleEnemy=ready&&units.some(e=>alive(e)&&e.team==='enemy'&&canReach(u,e));let possibleAlly=ready&&u.heal&&units.some(a=>alive(a)&&a.team==='player'&&a.id!==u.id&&a.hp<a.maxHp&&distance(a,u)<=1);$('attackBtn').disabled=!ready||u.heal>0||!possibleEnemy;$('healBtn').disabled=!ready||!u.heal||!possibleAlly;$('waitBtn').disabled=!ready;$('orderHint').textContent=!ready?'Select a ready hero':mode==='move'?'Drag to move':mode==='heal'?'Tap an ally':'Choose an action'}
function resizeCanvas(){if(!$('battleScreen').classList.contains('active'))return;let r=canvas.getBoundingClientRect(),dpr=Math.max(1,window.devicePixelRatio||1);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);geom={w:r.width,h:r.height,step:r.width/W,off:0};drawMap()}
function polyOct(x,y,s){let c=s*.22;ctx.beginPath();ctx.moveTo(x-s/2+c,y-s/2);ctx.lineTo(x+s/2-c,y-s/2);ctx.lineTo(x+s/2,y-s/2+c);ctx.lineTo(x+s/2,y+s/2-c);ctx.lineTo(x+s/2-c,y+s/2);ctx.lineTo(x-s/2+c,y+s/2);ctx.lineTo(x-s/2,y+s/2-c);ctx.lineTo(x-s/2,y-s/2+c);ctx.closePath()}
