function tileFromPoint(clientX,clientY){let r=canvas.getBoundingClientRect(),x=Math.floor((clientX-r.left)/geom.step),y=Math.floor((clientY-r.top)/geom.step);return x>=0&&y>=0&&x<W&&y<H?{x,y}:null}
