function beginPlayerAttack(a,d){if(!a||!d||a.acted||a.heal||!canReach(a,d))return;gameBusy=true;mode='move';moveSet.clear();renderAll();combat(a,d,()=>{a.acted=true;gameBusy=false;inspectId=d.hp>0?d.id:a.id;addLog(`<b>${a.name}</b> clashes with ${d.name}${d.hp<=0?' — defeated!':''}.`);afterPlayerAction()})}
function afterPlayerAction(){renderAll();if(units.filter(u=>u.team==='player'&&alive(u)).every(u=>u.acted))setTimeout(beginEnemyPhase,350)}

