function weaponGlyph(w){return w==='bow'?'➶':w.includes('tome')||w==='tome'?'✦':w==='axe'?'⚒':w==='staff'?'✧':w==='lance'?'⚝':'⚔'}
async function combat(a,d,done){showDuel(a,d);duelBusy=true;$('fighterA').classList.add('lunge');await pause(620);$('fighterA').classList.remove('lunge');let dealt=false;if(Math.random()<(terrain[d.y][d.x]==='forest'?.15:0)){ $('duelMessage').textContent=`${d.name} slips through the trees!`; }else{let amount=Math.max(1,a.atk-d.def);d.hp=Math.max(0,d.hp-amount);dealt=true;$('duelMessage').textContent=`${a.name} strikes for ${amount} damage!`}$('duelHpA').innerHTML=hpBarHTML(a);$('duelHpB').innerHTML=hpBarHTML(d);await pause(430);
 if(alive(d)&&alive(a)&&canReach(d,a)){ $('nameA').textContent=d.name;$('nameB').textContent=a.name;$('duelHpA').innerHTML=hpBarHTML(d);$('duelHpB').innerHTML=hpBarHTML(a);$('dmgStat').textContent=`DMG ${Math.max(1,d.atk-a.def)}`;$('hitStat').textContent=`HIT ${terrain[a.y][a.x]==='forest'?85:100} · CRIT 0`;$('duelMessage').textContent=`${d.name} counters!`;$('fighterB').classList.add('lunge');await pause(580);$('fighterB').classList.remove('lunge');if(Math.random()<(terrain[a.y][a.x]==='forest'?.15:0))$('duelMessage').textContent=`${a.name} dodges the counter!`;else{let amount=Math.max(1,d.atk-a.def);a.hp=Math.max(0,a.hp-amount);$('duelMessage').textContent=`${d.name} counters for ${amount} damage!`}$('duelHpA').innerHTML=hpBarHTML(d);$('duelHpB').innerHTML=hpBarHTML(a);await pause(420)}else await pause(180);
 $('duel').classList.remove('show');duelBusy=false;if(done)done()}
