function finish(win){gameBusy=true;phase='result';$('resultKicker').textContent=win?'BATTLE WON':'COMPANY DEFEATED';$('resultTitle').textContent=win?'Victory!':'The Ring Falls';$('resultText').textContent=win?`The bandits are routed. Your company has won Battle ${battle}. The next skirmish will bring a larger force and a fresh battlefield.`:'Every hero has fallen. Regroup and try this battle again.';$('resultBtn').textContent=win?'Continue to next battle':'Retry battle';$('resultBtn').onclick=()=>{if(win)battle++;startBattle()};$('resultModal').classList.add('show');renderAll()}
