async function enemyAct(e){let players=units.filter(u=>u.team==='player'&&alive(u));if(!players.length)return;players.sort((a,b)=>(distance(e,a)+a.hp/a.maxHp*.8)-(distance(e,b)+b.hp/b.maxHp*.8));let target=players[0];if(!canReach(e,target)){let options=reachable(e,e.move),best=null,score=Infinity;for(let [k,c] of options){let [x,y]=k.split(',').map(Number);if(x===e.x&&y===e.y)continue;let d={x,y};let near=Math.min(...players.map(p=>distance(d,p)));let v=near+c*.015;if(v<score){score=v;best=d}}if(best){e.x=best.x;e.y=best.y;addLog(`<b>${e.name}</b> closes in on your company.`);await pause(220)}}let victims=units.filter(u=>u.team==='player'&&alive(u)&&canReach(e,u)).sort((a,b)=>(a.hp/a.maxHp)-(b.hp/b.maxHp));let victim=victims[0];if(victim){addLog(`<b>${e.name}</b> attacks ${victim.name}.`);gameBusy=true;await new Promise(resolve=>combat(e,victim,resolve));gameBusy=true;inspectId=victim.id}}

