 for(let i=0;i<50;i++){const x=await call('Runtime.evaluate',{expression:'document.readyState',returnByValue:true});if(x.result.value==='complete')break;await sleep(100)}
 const expression=`(async()=>{
 const assert=(x,m)=>{if(!x)throw Error(m)};
 $('beginBtn').click();
 for(const heroId of ['alden','mira','bram','noel','sera'])document.querySelector('[data-id="'+heroId+'"]').click();
 assert(chosen.length===5,'deployment selection');$('deployBtn').click();
 assert(units.filter(u=>u.team==='player').length===5,'five heroes');assert(units.filter(u=>u.team==='enemy').length===5,'five enemies');
 const alden=byId('alden'),enemy=units.find(u=>u.team==='enemy');assert(alden&&enemy,'missing combatants');
