 const hpBefore=alden.hp;setSelection(alden);beginPlayerAttack(alden,enemy);
 await new Promise(r=>setTimeout(r,2400));assert(alden.acted,'attack action not consumed');assert(enemy.hp<enemy.maxHp,'attack caused no damage');assert(alden.hp<hpBefore,'living enemy did not counter');
 const mira=byId('mira'),weak=units.find(u=>u.team==='enemy'&&alive(u)&&u!==enemy);weak.x=mira.x+1;weak.y=mira.y;weak.hp=1;terrain[weak.y][weak.x]='plain';const miraHp=mira.hp;setSelection(mira);beginPlayerAttack(mira,weak);
