 const healer=byId('noel'),ally=alden;healer.x=ally.x+1;healer.y=ally.y;terrain[healer.y][healer.x]='plain';ally.hp=ally.maxHp-5;healer.acted=false;setSelection(healer);healUnit(healer,ally);assert(ally.hp===ally.maxHp,'heal did not restore HP');assert(healer.acted,'healer action not consumed');
 const mover=byId('bram');mover.acted=false;setSelection(mover);const reach=[...moveSet.keys()].find(k=>k!==key(mover.x,mover.y));assert(reach,'no reachable movement tile');const [x,y]=reach.split(',').map(Number);moveUnit(mover,x,y);assert(mover.moved,'movement not recorded');
 const waiter=byId('sera');setSelection(waiter);$('waitBtn').click();assert(waiter.acted,'wait did not consume action');
